using System.Text.Json;using Microsoft.Data.SqlClient;using var cfg=JsonDocument.Parse(File.ReadAllText("Admin/appsettings.json"));await using var cn=new SqlConnection(cfg.RootElement.GetProperty("ConnectionStrings").GetProperty("DefaultConnection").GetString());await cn.OpenAsync();await using var cmd=cn.CreateCommand();cmd.CommandText="SELECT COUNT_BIG(*) FROM (SELECT p.Id,COUNT(c.Id) CenterCount FROM Geo.Province p LEFT JOIN Geo.City c ON c.IdProvince=p.Id AND c.IsProvinceCenter=1 GROUP BY p.Id HAVING COUNT(c.Id)<>1) x";Console.WriteLine("provinces_without_exactly_one_center="+await cmd.ExecuteScalarAsync());
